  var base=world.resolve("data/zianmanager");var file=base.resolve("npc_trades.json");boolean restart=Files.exists(base.resolve("multi-trade-passed.json"));if(restart)check(NpcTrading.get().rows(fake(server.overworld(),520),NPC).getFirst().payments().size()==3,"Multi-item offer lost after restart");
