  var menu=menu(p,npc);p.containerMenu=menu;
  check(menu.getSlot(0).getItem().getCount()==4&&menu.getSlot(2).getItem().getCount()==3&&menu.getSlot(3).getItem().isEmpty(),"Payment previews wrong");check(ItemStack.isSameItemSameComponents(menu.getSlot(5).getItem(),hammer),"Output preview lost components");
  inputs(p,iron,diamond,key);var before=snapshot(p);for(int i=0;i<8;i++){menu.clicked(i,0,ClickType.PICKUP,p);menu.clicked(i,0,ClickType.SWAP,p);check(menu.quickMoveStack(p,i).isEmpty(),"Preview moved by shift-click");}check(same(p,before)&&menu.getCarried().isEmpty(),"Preview extraction changed inventory");
