  for(int i=0;i<600;i++){inputs(p,iron,diamond,key);check(menu.clickMenuButton(p,64)&&count(p,Items.GOLD_INGOT)==2&&count(p,hammer.getItem())==1,"Unlimited bundled trade failed at "+i);}
  inputs(p,iron,diamond,key);before=snapshot(p);p.moveTo(p.getX()+20,p.getY(),p.getZ());check(!menu.stillValid(p)&&!menu.clickMenuButton(p,64)&&same(p,before),"Remote trade executed");p.moveTo(npc.position());var other=fake(level,522);check(!menu.clickMenuButton(other,64)&&same(p,before),"Another player used owner's menu");check(!menu.clickMenuButton(p,-1)&&!menu.clickMenuButton(p,65)&&same(p,before),"Invalid button executed a trade");menu.removed(p);check(same(p,before),"Closing changed unspent materials");
  // Four prices/four rewards, duplicated types, split stacks, and nonstackable rewards.
  var four=new com.ianblk.zianmanager.core.NpcTradeData.Offer(List.of(save(p,iron),save(p,iron),save(p,diamond),save(p,key)),List.of(save(p,gold.copyWithCount(1)),save(p,gold),save(p,hammer),save(p,hammer)));AtomicJson.write(file,new com.ianblk.zianmanager.core.NpcTradeData.Data(2,Map.of(NPC,List.of(four))));new NpcTrading(file);menu=menu(p,npc);p.containerMenu=menu;inputs(p,iron.copyWithCount(3),diamond,key);p.getInventory().setItem(10,iron.copyWithCount(5));check(menu.clickMenuButton(p,64)&&count(p,Items.RAW_IRON)==0&&count(p,Items.GOLD_INGOT)==3&&count(p,hammer.getItem())==2,"4-to-4 aggregation or nonstackable delivery failed");
  var reverse=new com.ianblk.zianmanager.core.NpcTradeData.Offer(List.of(save(p,iron),save(p,diamond)),List.of(save(p,gold),save(p,key),save(p,hammer)));AtomicJson.write(file,new com.ianblk.zianmanager.core.NpcTradeData.Data(2,Map.of(NPC,List.of(reverse))));new NpcTrading(file);menu=menu(p,npc);p.containerMenu=menu;inputs(p,iron,diamond);check(menu.clickMenuButton(p,64)&&count(p,key.getItem())==3&&count(p,hammer.getItem())==1,"2-to-3 trade failed");
  var named=key.copy();named.set(DataComponents.CUSTOM_NAME,Component.literal("Llave de misión"));var restricted=new com.ianblk.zianmanager.core.NpcTradeData.Offer(List.of(save(p,named)),List.of(save(p,gold)));AtomicJson.write(file,new com.ianblk.zianmanager.core.NpcTradeData.Data(2,Map.of(NPC,List.of(restricted))));new NpcTrading(file);menu=menu(p,npc);p.containerMenu=menu;inputs(p,key);before=snapshot(p);check(!menu.clickMenuButton(p,64)&&same(p,before),"Named payment accepted generic key");inputs(p,named);check(menu.clickMenuButton(p,64)&&count(p,Items.GOLD_INGOT)==2,"Correct named payment rejected");
  var nameOnly=key.copyWithCount(1);nameOnly.set(DataComponents.CUSTOM_NAME,Component.literal("Llave especial"));var loreOnly=key.copyWithCount(1);loreOnly.set(DataComponents.LORE,new net.minecraft.world.item.component.ItemLore(List.of(Component.literal("Marca de misión"))));var both=nameOnly.copy();both.set(DataComponents.LORE,loreOnly.get(DataComponents.LORE));var overlap=new com.ianblk.zianmanager.core.NpcTradeData.Offer(List.of(save(p,nameOnly),save(p,loreOnly)),List.of(save(p,gold)));AtomicJson.write(file,new com.ianblk.zianmanager.core.NpcTradeData.Data(2,Map.of(NPC,List.of(overlap))));new NpcTrading(file);menu=menu(p,npc);p.containerMenu=menu;inputs(p,both,nameOnly);check(menu.clickMenuButton(p,64)&&count(p,key.getItem())==0&&count(p,Items.GOLD_INGOT)==2,"Overlapping component predicates allocated the same item incorrectly");
