  server.getPlayerList().op(p.getGameProfile());NpcTrading.get().edit(p,NPC);NpcTrading.get().action(p,new ManagerNetwork.Action(token(p),"trade_remove","{\"index\":0}"));check(!menu.stillValid(p)&&!menu.clickMenuButton(p,64)&&same(p,before),"Stale edited offer executed");server.getPlayerList().deop(p.getGameProfile());
  var saved=new com.ianblk.zianmanager.core.NpcTradeData.Offer(List.of(save(p,iron),save(p,diamond),save(p,key)),List.of(save(p,gold),save(p,hammer)));AtomicJson.write(file,new com.ianblk.zianmanager.core.NpcTradeData.Data(2,Map.of(NPC,List.of(saved))));new NpcTrading(file);
